module hdmi_audio_tone_i2s_64fs #(
    parameter integer STRONG_COUNT     = 1614,
    parameter integer WEAK_COUNT       = 1890,
    parameter integer CLICK_COUNT      = 6046,
    parameter integer METRO_LEFT_SHIFT = 7,
    parameter integer CLICK_LEFT_SHIFT = 6
)(
    input  wire I_mclk,              // 12.288MHz
    input  wire I_rst,
    input  wire I_strong_toggle,
    input  wire I_weak_toggle,
    input  wire I_click_toggle,
    input  wire I_piano_c4_gate,
    input  wire I_piano_d4_gate,
    input  wire I_piano_e4_gate,

    // V16: asynchronous true-dual-port C4 PCM cache.
    // Write side is sd_card_clk; read side is I_mclk.
    input  wire        I_c4_pcm_wr_clk,
    input  wire        I_c4_pcm_wr_en,
    input  wire [11:0] I_c4_pcm_wr_addr,
    input  wire [15:0] I_c4_pcm_wr_data,
    input  wire        I_c4_pcm_ready,

    output reg  O_i2s_BCLK,
    output reg  O_i2s_LRCK,
    output reg  O_i2s_DOUT
);

localparam integer METRO_ROM_DEPTH  = 2048;
localparam integer METRO_ADDR_WIDTH = 11;
localparam integer CLICK_ROM_DEPTH  = 8192;
localparam integer CLICK_ADDR_WIDTH = 13;

