// ---------------------------------------------------------------------------
// 三条独立 toggle CDC：50MHz -> 12.288MHz
// ---------------------------------------------------------------------------
reg [2:0] S_strong_sync;
reg [2:0] S_weak_sync;
reg [2:0] S_click_sync;

// V10：三个持续 gate 分别同步到 12.288MHz 音频域。
// 这是当前板载三键复音的最小验证路径；以后再替换成通用 Voice Allocator。
reg [2:0] S_c4_gate_sync;
reg [2:0] S_d4_gate_sync;
reg [2:0] S_e4_gate_sync;
reg [2:0] S_c4_pcm_ready_sync;

wire W_strong_pulse = S_strong_sync[2] ^ S_strong_sync[1];
wire W_weak_pulse   = S_weak_sync[2]   ^ S_weak_sync[1];
wire W_click_pulse  = S_click_sync[2]  ^ S_click_sync[1];

wire W_c4_gate = S_c4_gate_sync[2];
wire W_d4_gate = S_d4_gate_sync[2];
wire W_e4_gate = S_e4_gate_sync[2];
wire W_c4_pcm_ready = S_c4_pcm_ready_sync[2];

// ---------------------------------------------------------------------------
// 节拍器采样轨
// ---------------------------------------------------------------------------
reg [METRO_ADDR_WIDTH-1:0] S_metro_addr;
reg [METRO_ADDR_WIDTH-1:0] S_metro_index;
reg signed [15:0] S_strong_q;
reg signed [15:0] S_weak_q;
reg S_metro_playing;
reg S_play_strong;

always @(posedge I_mclk) begin
    S_strong_q <= S_strong_rom[S_metro_addr];
    S_weak_q   <= S_weak_rom[S_metro_addr];
end

wire signed [15:0] W_metro_pcm16 =
    S_play_strong ? S_strong_q : S_weak_q;

wire signed [23:0] W_metro_pcm24 =
    {{8{W_metro_pcm16[15]}}, W_metro_pcm16};

wire signed [23:0] W_metro_sample =
    S_metro_playing ? (W_metro_pcm24 <<< METRO_LEFT_SHIFT) : 24'sd0;

wire [METRO_ADDR_WIDTH-1:0] W_metro_last_index =
    S_play_strong ? (STRONG_COUNT - 1) : (WEAK_COUNT - 1);

// ---------------------------------------------------------------------------
// UI按键音效采样轨
// ---------------------------------------------------------------------------
reg [CLICK_ADDR_WIDTH-1:0] S_click_addr;
reg [CLICK_ADDR_WIDTH-1:0] S_click_index;
reg signed [15:0] S_click_q;
reg S_click_playing;

always @(posedge I_mclk) begin
    S_click_q <= S_click_rom[S_click_addr];
end

wire signed [23:0] W_click_pcm24 =
    {{8{S_click_q[15]}}, S_click_q};

wire signed [23:0] W_click_sample =
    S_click_playing ? (W_click_pcm24 <<< CLICK_LEFT_SHIFT) : 24'sd0;

// ---------------------------------------------------------------------------
// V10：SW3 琴键测试音源 - 3 Voice DDS
// ---------------------------------------------------------------------------
// 当前只做 C4 / D4 / E4 三个独立 Voice，先验证真正的同时发声。
// phase_step = round(f * 2^32 / 48000)
localparam [31:0] C4_PHASE_STEP = 32'd23409859; // 261.6256 Hz
localparam [31:0] D4_PHASE_STEP = 32'd26276679; // 293.6648 Hz
localparam [31:0] E4_PHASE_STEP = 32'd29494575; // 329.6276 Hz

reg [31:0] S_c4_phase;
reg [31:0] S_d4_phase;
reg [31:0] S_e4_phase;

// ---------------------------------------------------------------------------
// V16: C4 TF-loaded real-piano PCM cache
// ---------------------------------------------------------------------------
// 4096 samples @48kHz = 85.33ms, 8KiB.
// This is a verification cache only.  The final multi-instrument design will
// move full banks to external SDRAM rather than keep adding BRAM per note.
// V17 simple sound-quality tweak:
// - move the loop boundary to a waveform-matched pair with a smaller jump;
// - keep this as a temporary short-loop solution until full SDRAM samples.
localparam [11:0] C4_PCM_LOOP_START = 12'd2097;
localparam [11:0] C4_PCM_LOOP_LAST  = 12'd3752;

// While the key is held, a real piano does not stay at full level forever.
// Decay from full scale to ~25% in about 1.02 s, then hold there.
// (4095-1024) * 16 / 48000 ~= 1.024 s
localparam [11:0] C4_HOLD_FLOOR = 12'd1024;

reg [11:0] S_c4_pcm_addr;
wire signed [15:0] W_c4_pcm_q;

reg        S_c4_gate_prev;
reg        S_c4_retrigger_pending;
reg        S_c4_use_pcm;

wire W_c4_gate_rise = W_c4_gate && !S_c4_gate_prev;

// True dual-port RAM: SD writes, audio reads.
c4_pcm_dp_ram u_c4_pcm_dp_ram (
    .wr_clk  (I_c4_pcm_wr_clk),
    .wr_en   (I_c4_pcm_wr_en),
    .wr_addr (I_c4_pcm_wr_addr),
    .wr_data (I_c4_pcm_wr_data),

    .rd_clk  (I_mclk),
    .rd_addr (S_c4_pcm_addr),
    .rd_data (W_c4_pcm_q)
);

// ---------------------------------------------------------------------------
// V13：三个 Voice 各自增加 Release 包络
// ---------------------------------------------------------------------------
// 12-bit envelope：0~4095。
// 松键后不是立即清零，而是每4个48kHz sample减1：
//   4095 * 4 / 48000 = 0.34125 s
// 即约 341 ms 的线性 Release。
reg [11:0] S_c4_env;
reg [11:0] S_d4_env;
reg [11:0] S_e4_env;

// C4 gets a slightly more piano-like envelope in V17.
// Hold decay: one envelope step every 16 samples.
// Release:    one envelope step every 8 samples.
reg [3:0] S_c4_hold_decay_div;
reg [2:0] S_c4_release_div;

reg [1:0] S_d4_release_div;
reg [1:0] S_e4_release_div;

// gate=0 后，只要 envelope 还没衰减到0，这个 Voice 仍然属于 active。
// 因此相位会继续推进，声音形成真正的尾音，而不是松键瞬间停止。
wire W_c4_active = W_c4_gate || (S_c4_env != 12'd0);
wire W_d4_active = W_d4_gate || (S_d4_env != 12'd0);
wire W_e4_active = W_e4_gate || (S_e4_env != 12'd0);

wire [1:0] W_voice_count =
    {1'b0,W_c4_active} + {1'b0,W_d4_active} + {1'b0,W_e4_active};

// 把 12-bit envelope 转成每个 Voice 的幅度。
// 不使用乘法器，只用移位/加法，尽量保持这一步资源和时序简单：
//
// 1 Voice: env * 512 -> full scale约 2,096,640
// 2 Voice: env * 256 -> 每路约 1,048,320
// 3 Voice: env * 170 -> 每路约   696,150
//
// 3 Voice 的 170 = 128 + 32 + 8 + 2。
function [23:0] env_to_amp;
    input [11:0] env;
    input [1:0]  voice_count;
    reg [23:0] e;
    begin
        e = {12'd0, env};
        case (voice_count)
            2'd1: env_to_amp = e << 9;
            2'd2: env_to_amp = e << 8;
            2'd3: env_to_amp = (e << 7) + (e << 5) + (e << 3) + (e << 1);
            default: env_to_amp = 24'd0;
        endcase
    end
endfunction

wire [23:0] W_c4_amp_mag = env_to_amp(S_c4_env, W_voice_count);
wire [23:0] W_d4_amp_mag = env_to_amp(S_d4_env, W_voice_count);
wire [23:0] W_e4_amp_mag = env_to_amp(S_e4_env, W_voice_count);

wire signed [23:0] W_c4_amp = $signed(W_c4_amp_mag);
wire signed [23:0] W_d4_amp = $signed(W_d4_amp_mag);
wire signed [23:0] W_e4_amp = $signed(W_e4_amp_mag);

wire signed [23:0] W_c4_dds_sample =
    W_c4_active ? (S_c4_phase[31] ? -W_c4_amp : W_c4_amp) : 24'sd0;

// 16-bit signed PCM * 12-bit Release envelope.
// 29-bit product is easy at 12.288MHz and keeps the existing Release behavior.
wire signed [28:0] W_c4_pcm_env_product =
    $signed(W_c4_pcm_q) * $signed({1'b0, S_c4_env});

// Keep total piano headroom close to the already-stable V13 mixer.
// Current source C4 peak is lower than full-scale, so one-voice path gets
// slightly more gain than the DDS path.
wire signed [28:0] W_c4_pcm_scaled =
    (W_voice_count == 2'd1) ? (W_c4_pcm_env_product >>> 5) :
    (W_voice_count == 2'd2) ? (W_c4_pcm_env_product >>> 6) :
    (W_voice_count == 2'd3) ? ((W_c4_pcm_env_product >>> 7) +
                               (W_c4_pcm_env_product >>> 8)) :
                              29'sd0;

wire signed [23:0] W_c4_pcm_sample =
    // Mute only the one sample-frame used to re-prime address0 on NOTE_ON.
    (S_c4_retrigger_pending) ? 24'sd0 : W_c4_pcm_scaled[23:0];

wire signed [23:0] W_c4_sample =
    W_c4_active
        ? (S_c4_use_pcm ? W_c4_pcm_sample : W_c4_dds_sample)
        : 24'sd0;

wire signed [23:0] W_d4_sample =
    W_d4_active ? (S_d4_phase[31] ? -W_d4_amp : W_d4_amp) : 24'sd0;

wire signed [23:0] W_e4_sample =
    W_e4_active ? (S_e4_phase[31] ? -W_e4_amp : W_e4_amp) : 24'sd0;

wire signed [26:0] W_mix_sum =
    {{3{W_metro_sample[23]}}, W_metro_sample} +
    {{3{W_click_sample[23]}}, W_click_sample} +
    {{3{W_c4_sample[23]}}, W_c4_sample} +
    {{3{W_d4_sample[23]}}, W_d4_sample} +
    {{3{W_e4_sample[23]}}, W_e4_sample};

wire signed [23:0] W_mix_sample = W_mix_sum[23:0];

// ---------------------------------------------------------------------------
// 64fs I2S 状态
// ---------------------------------------------------------------------------
reg [5:0]  S_bit_cnt;
reg [63:0] S_shift_reg;
reg signed [23:0] S_sample_word;

always @(posedge I_mclk or posedge I_rst) begin
    if (I_rst) begin
        S_strong_sync   <= 3'b000;
        S_weak_sync     <= 3'b000;
        S_click_sync    <= 3'b000;
        S_c4_gate_sync  <= 3'b000;
        S_d4_gate_sync  <= 3'b000;
        S_e4_gate_sync  <= 3'b000;
        S_c4_pcm_ready_sync <= 3'b000;

        O_i2s_BCLK       <= 1'b0;
        O_i2s_LRCK       <= 1'b0;
        O_i2s_DOUT       <= 1'b0;

        S_metro_addr     <= {METRO_ADDR_WIDTH{1'b0}};
        S_metro_index    <= {METRO_ADDR_WIDTH{1'b0}};
        S_metro_playing  <= 1'b0;
        S_play_strong    <= 1'b0;

        S_click_addr     <= {CLICK_ADDR_WIDTH{1'b0}};
        S_click_index    <= {CLICK_ADDR_WIDTH{1'b0}};
        S_click_playing  <= 1'b0;

        S_c4_phase       <= 32'd0;
        S_d4_phase       <= 32'd0;
        S_e4_phase       <= 32'd0;

        S_c4_pcm_addr          <= 12'd0;
        S_c4_gate_prev         <= 1'b0;
        S_c4_retrigger_pending <= 1'b0;
        S_c4_use_pcm           <= 1'b0;

        S_c4_env            <= 12'd0;
        S_d4_env            <= 12'd0;
        S_e4_env            <= 12'd0;
        S_c4_hold_decay_div <= 4'd0;
        S_c4_release_div    <= 3'd0;
        S_d4_release_div    <= 2'd0;
        S_e4_release_div    <= 2'd0;

        S_bit_cnt        <= 6'd0;
        S_shift_reg      <= 64'd0;
        S_sample_word    <= 24'sd0;
    end
    else begin
        S_strong_sync  <= {S_strong_sync[1:0], I_strong_toggle};
        S_weak_sync    <= {S_weak_sync[1:0], I_weak_toggle};
        S_click_sync   <= {S_click_sync[1:0], I_click_toggle};
        S_c4_gate_sync <= {S_c4_gate_sync[1:0], I_piano_c4_gate};
        S_d4_gate_sync <= {S_d4_gate_sync[1:0], I_piano_d4_gate};
        S_e4_gate_sync <= {S_e4_gate_sync[1:0], I_piano_e4_gate};
        S_c4_pcm_ready_sync <= {S_c4_pcm_ready_sync[1:0], I_c4_pcm_ready};

        S_c4_gate_prev <= W_c4_gate;

        // NOTE_ON chooses PCM only if the TF cache was already fully loaded.
        // If the user presses very early during startup, that one note falls
        // back to the old DDS; the next NOTE_ON will use piano PCM.
        if (W_c4_gate_rise) begin
            S_c4_use_pcm           <= W_c4_pcm_ready;
            S_c4_retrigger_pending <= 1'b1;
        end

        // 节拍器：strong优先
        if (W_strong_pulse) begin
            S_metro_playing <= 1'b1;
            S_play_strong   <= 1'b1;
            S_metro_addr    <= {METRO_ADDR_WIDTH{1'b0}};
            S_metro_index   <= {METRO_ADDR_WIDTH{1'b0}};
        end
        else if (W_weak_pulse) begin
            S_metro_playing <= 1'b1;
            S_play_strong   <= 1'b0;
            S_metro_addr    <= {METRO_ADDR_WIDTH{1'b0}};
            S_metro_index   <= {METRO_ADDR_WIDTH{1'b0}};
        end

        // UI click：每次新按键都从样本头重新触发
        if (W_click_pulse) begin
            S_click_playing <= 1'b1;
            S_click_addr    <= {CLICK_ADDR_WIDTH{1'b0}};
            S_click_index   <= {CLICK_ADDR_WIDTH{1'b0}};
        end

        // 保持前几步已经实机验证稳定的I2S时序
        O_i2s_BCLK <= ~O_i2s_BCLK;

        if (O_i2s_BCLK == 1'b1) begin
            O_i2s_DOUT  <= S_shift_reg[63];
            S_shift_reg <= {S_shift_reg[62:0], 1'b0};

            if (S_bit_cnt == 6'd63) begin
                S_bit_cnt <= 6'd0;

                if (O_i2s_LRCK == 1'b0) begin
                    // 左声道结束，右声道使用同一混合采样
                    O_i2s_LRCK  <= 1'b1;
                    S_shift_reg <= {S_sample_word[23:0], 40'd0};
                end
                else begin
                    // 右声道结束，生成下一帧48kHz混合采样
                    O_i2s_LRCK    <= 1'b0;
                    S_sample_word <= W_mix_sample;
                    S_shift_reg   <= {W_mix_sample[23:0], 40'd0};

                    // -------------------------------------------------------
                    // V13：3 Voice Release，只在48kHz sample tick更新。
                    // -------------------------------------------------------

                    // ---------------------------------------------------
                    // V17 C4 envelope:
                    // NOTE_ON -> full level.
                    // HOLD    -> slowly decay toward 25% instead of keeping
                    //            the short PCM loop at full loudness forever.
                    // NOTE_OFF-> longer, softer release.
                    // ---------------------------------------------------
                    if (S_c4_retrigger_pending) begin
                        S_c4_env            <= 12'd4095;
                        S_c4_hold_decay_div <= 4'd0;
                        S_c4_release_div    <= 3'd0;
                    end
                    else if (W_c4_gate) begin
                        S_c4_release_div <= 3'd0;

                        if (S_c4_env > C4_HOLD_FLOOR) begin
                            if (S_c4_hold_decay_div == 4'd15) begin
                                S_c4_hold_decay_div <= 4'd0;
                                S_c4_env            <= S_c4_env - 12'd1;
                            end
                            else begin
                                S_c4_hold_decay_div <= S_c4_hold_decay_div + 4'd1;
                            end
                        end
                        else begin
                            S_c4_hold_decay_div <= 4'd0;
                        end
                    end
                    else if (S_c4_env != 12'd0) begin
                        S_c4_hold_decay_div <= 4'd0;

                        // 4095 * 8 / 48000 ~= 682 ms from full level.
                        // If the note has already decayed while held, the
                        // remaining release is naturally shorter.
                        if (S_c4_release_div == 3'd7) begin
                            S_c4_release_div <= 3'd0;
                            S_c4_env         <= S_c4_env - 12'd1;
                        end
                        else begin
                            S_c4_release_div <= S_c4_release_div + 3'd1;
                        end
                    end
                    else begin
                        S_c4_hold_decay_div <= 4'd0;
                        S_c4_release_div    <= 3'd0;
                    end

                    if (W_d4_gate) begin
                        S_d4_env         <= 12'd4095;
                        S_d4_release_div <= 2'd0;
                    end
                    else if (S_d4_env != 12'd0) begin
                        if (S_d4_release_div == 2'd3) begin
                            S_d4_release_div <= 2'd0;
                            S_d4_env         <= S_d4_env - 12'd1;
                        end
                        else
                            S_d4_release_div <= S_d4_release_div + 2'd1;
                    end
                    else
                        S_d4_release_div <= 2'd0;

                    if (W_e4_gate) begin
                        S_e4_env         <= 12'd4095;
                        S_e4_release_div <= 2'd0;
                    end
                    else if (S_e4_env != 12'd0) begin
                        if (S_e4_release_div == 2'd3) begin
                            S_e4_release_div <= 2'd0;
                            S_e4_env         <= S_e4_env - 12'd1;
                        end
                        else
                            S_e4_release_div <= S_e4_release_div + 2'd1;
                    end
                    else
                        S_e4_release_div <= 2'd0;

                    // V16 C4:
                    // - PCM note starts at address0;
                    // - held/release voice keeps moving through the sample;
                    // - after the attack, loop the current C4 sustain region;
                    // - DDS phase still advances as a startup fallback.
                    if (S_c4_use_pcm) begin
                        if (S_c4_retrigger_pending) begin
                            S_c4_pcm_addr          <= 12'd0;
                            S_c4_retrigger_pending <= 1'b0;
                        end
                        else if (W_c4_active) begin
                            if (S_c4_pcm_addr >= C4_PCM_LOOP_LAST)
                                S_c4_pcm_addr <= C4_PCM_LOOP_START;
                            else
                                S_c4_pcm_addr <= S_c4_pcm_addr + 12'd1;
                        end
                        else begin
                            S_c4_pcm_addr <= 12'd0;
                        end
                    end
                    else begin
                        // Clear a pending retrigger even when this particular
                        // note is using DDS because the TF cache was not ready.
                        S_c4_retrigger_pending <= 1'b0;
                        S_c4_pcm_addr <= 12'd0;
                    end

                    if (W_c4_active)
                        S_c4_phase <= S_c4_phase + C4_PHASE_STEP;
                    else begin
                        S_c4_phase   <= 32'd0;
                        S_c4_use_pcm <= 1'b0;
                    end

                    if (W_d4_active)
                        S_d4_phase <= S_d4_phase + D4_PHASE_STEP;
                    else
                        S_d4_phase <= 32'd0;

                    if (W_e4_active)
                        S_e4_phase <= S_e4_phase + E4_PHASE_STEP;
                    else
                        S_e4_phase <= 32'd0;

                    // 推进节拍器轨
                    if (S_metro_playing) begin
                        if (S_metro_index >= W_metro_last_index) begin
                            S_metro_playing <= 1'b0;
                            S_metro_index   <= {METRO_ADDR_WIDTH{1'b0}};
                            S_metro_addr    <= {METRO_ADDR_WIDTH{1'b0}};
                        end
                        else begin
                            S_metro_index <= S_metro_index + 1'b1;
                            S_metro_addr  <= S_metro_addr + 1'b1;
                        end
                    end

                    // 推进按键音效轨
                    if (S_click_playing) begin
                        if (S_click_index >= CLICK_COUNT - 1) begin
                            S_click_playing <= 1'b0;
                            S_click_index   <= {CLICK_ADDR_WIDTH{1'b0}};
                            S_click_addr    <= {CLICK_ADDR_WIDTH{1'b0}};
                        end
                        else begin
                            S_click_index <= S_click_index + 1'b1;
                            S_click_addr  <= S_click_addr + 1'b1;
                        end
                    end
                end
            end
            else begin
                S_bit_cnt <= S_bit_cnt + 6'd1;
            end
        end
    end
end

endmodule

// ===========================================================================
// V16 C4 dynamic PCM cache
// ===========================================================================
// Write port:  sd_card_clk (during startup TF scan)
// Read port:   audio_mclk
//
// The memory has no reset; piano_c4_pcm_ready is asserted only after all 4096
// locations have been filled, so uninitialized contents are never selected.
module c4_pcm_dp_ram (
    input  wire        wr_clk,
    input  wire        wr_en,
    input  wire [11:0] wr_addr,
    input  wire [15:0] wr_data,

    input  wire        rd_clk,
    input  wire [11:0] rd_addr,
    output reg signed [15:0] rd_data
);

reg signed [15:0] mem [0:4095]
    /* fehdl force_ram=1, ram_style="bram" */;

always @(posedge wr_clk) begin
    if (wr_en)
        mem[wr_addr] <= wr_data;
end

always @(posedge rd_clk) begin
    rd_data <= mem[rd_addr];
end

endmodule
